select json_object('rl', regexp_like(p.title, 'a'), 'isn', isnull(p.tag), 'rx', p.title regexp 'a', 'ns', p.tag <=> null, 'it', p.n is true, 'ex', exists(select 1 from users), 'ins', p.n in (select id from users), 'co', coalesce(p.n = 1, false), 'if', if(p.n = 1, true, false), 'cs', case when p.n = 1 then true else false end, 'an', p.n = 1 and p.id = 2, 'xo', p.n xor 1, 'nt', not p.n, 'jc', json_contains('[1]', '1'), 'c', count(*)) as o from posts p group by p.id
